Below is a **self‑contained console application** that demonstrates the most common ways to use LINQ in C#.  
It covers:

1. **Creating a data set** (`List<Person>`).
2. **Query syntax** (the “`from … where … select …`” style).
3. **Method syntax** (the fluent `Where`, `Select`, `OrderBy`, etc. style).
4. **Group by** and **aggregation**.
5. **Joining** two collections.
6. **Using the result** (printing to the console).

```csharp
// ------------------------------------------------------------
// LINQDemo.cs
// ------------------------------------------------------------
using System;
using System.Collections.Generic;
using System.Linq;

namespace LINQDemo
{
    // 1. Define a simple POCO to work with
    public class Person
    {
        public string Name      { get; set; }
        public int    Age       { get; set; }
        public string City      { get; set; }
        public double Salary    { get; set; }

        public override string ToString()
        {
            return $"{Name,-10} {Age,3}  {City,-12} {Salary,8:C}";
        }
    }

    class Program
    {
        static void Main()
        {
            // --------------------------------------------------------
            // 2. Seed a collection of people
            // --------------------------------------------------------
            var people = new List<Person>
            {
                new Person{ Name="Alice",  Age=30, City="Seattle",  Salary=75000 },
                new Person{ Name="Bob",    Age=45, City="Boston",   Salary=85000 },
                new Person{ Name="Carol",  Age=25, City="Seattle",  Salary=62000 },
                new Person{ Name="Dave",   Age=35, City="New York", Salary=93000 },
                new Person{ Name="Eve",    Age=28, City="Boston",   Salary=72000 },
                new Person{ Name="Frank",  Age=52, City="Chicago",  Salary=88000 },
                new Person{ Name="Grace",  Age=41, City="Seattle",  Salary=82000 },
                new Person{ Name="Heidi",  Age=38, City="New York", Salary=96000 },
                new Person{ Name="Ivan",   Age=29, City="Chicago",  Salary=68000 },
                new Person{ Name="Judy",   Age=33, City="Boston",   Salary=79000 }
            };

            // --------------------------------------------------------
            // 3. Query syntax – filter, project, order
            // --------------------------------------------------------
            var querySyntax = 
                from p in people
                where p.Age >= 30 && p.City == "Seattle"
                orderby p.Salary descending
                select new { p.Name, p.Salary };

            Console.WriteLine("=== Query Syntax (Seattle, Age >= 30) ===");
            foreach (var item in querySyntax)
            {
                Console.WriteLine($"{item.Name,-10} {item.Salary,8:C}");
            }
            Console.WriteLine();

            // --------------------------------------------------------
            // 4. Method syntax – same logic, fluent style
            // --------------------------------------------------------
            var methodSyntax =
                people
                .Where(p => p.Age >= 30 && p.City == "Seattle")
                .OrderByDescending(p => p.Salary)
                .Select(p => new { p.Name, p.Salary });

            Console.WriteLine("=== Method Syntax (Seattle, Age >= 30) ===");
            foreach (var item in methodSyntax)
            {
                Console.WriteLine($"{item.Name,-10} {item.Salary,8:C}");
            }
            Console.WriteLine();

            // --------------------------------------------------------
            // 5. Group By + Aggregation
            // --------------------------------------------------------
            var avgSalaryByCity = 
                people
                .GroupBy(p => p.City)
                .Select(g => new { City = g.Key, AvgSalary = g.Average(p => p.Salary) });

            Console.WriteLine("=== Average Salary by City ===");
            foreach (var group in avgSalaryByCity)
            {
                Console.WriteLine($"{group.City,-12} {group.AvgSalary,10:C}");
            }
            Console.WriteLine();

            // --------------------------------------------------------
            // 6. Joining two collections
            // --------------------------------------------------------
            var cities = new List<string>
            {
                "Seattle", "Boston", "New York", "Chicago", "Los Angeles"
            };

            var peopleByCity =
                from city in cities
                join p in people on city equals p.City into gj
                select new
                {
                    City   = city,
                    Count  = gj.Count(),
                    People = gj.Select(x => x.Name).ToList()
                };

            Console.WriteLine("=== Join Cities with People ===");
            foreach (var item in peopleByCity)
            {
                Console.WriteLine($"{item.City,-12} ({item.Count,2} people): {string.Join(", ", item.People)}");
            }
        }
    }
}
```

### What the code does

| Step | What you’ll see in the console |
|------|--------------------------------|
| **Query syntax** | Lists people in Seattle who are at least 30 years old, ordered by salary. |
| **Method syntax** | Same result as above, but written with method calls. |
| **Group by & aggregate** | Calculates the average salary for each city. |
| **Join** | Shows how many people live in each city (including cities with no people). |

### Why it illustrates LINQ

* **`using System.Linq;`** brings in the extension methods and query operators.
* **Query syntax** (`from … where … select`) demonstrates the declarative style.
* **Method syntax** (`Where`, `OrderByDescending`, `Select`, `GroupBy`, `Join`) shows the fluent API.
* **Projection** (`select new { … }`) lets you shape the output.
* **Grouping** (`GroupBy`) and **aggregation** (`Average`, `Count`) are core LINQ features.
* **Joining** demonstrates how to combine two collections in a single query.

You can copy this file into a new **Console App (.NET Core)** project, run it, and see LINQ in action. Happy coding!
